@Service
public class CostAwareChatService {

    private final ChatModel chatModel;
    private final MeterRegistry meterRegistry;

    // Track token usage as counters
    public String ask(String feature, Prompt prompt) {
        ChatResponse response = chatModel.call(prompt);

        Usage usage = response.getMetadata().getUsage();
        Long promptTokens     = usage.getPromptTokens();
        Long completionTokens = usage.getGenerationTokens();

        Counter.builder("llm.tokens")
            .tag("type", "prompt")
            .tag("feature", feature)
            .register(meterRegistry)
            .increment(promptTokens);

        Counter.builder("llm.tokens")
            .tag("type", "completion")
            .tag("feature", feature)
            .register(meterRegistry)
            .increment(completionTokens);

        return response.getResult().getOutput().getContent();
    }
}

// ChatOptions to cap per-request token spend
ChatOptions bounded = ChatOptionsBuilder.builder()
    .withMaxTokens(500)   // hard cap on completion tokens
    .build();
