@Service
public class ObservableChatService {

    private final ChatModel chatModel;
    private final ObservationRegistry observationRegistry;
    private final MeterRegistry meterRegistry;

    public String generate(String feature, Prompt prompt) {
        // Timer — full call latency
        Timer.Sample sample = Timer.start(meterRegistry);

        try {
            ChatResponse response = chatModel.call(prompt);

            // Token counters
            Usage usage = response.getMetadata().getUsage();
            meterRegistry.counter("llm.tokens", "type", "prompt",   "feature", feature)
                         .increment(usage.getPromptTokens());
            meterRegistry.counter("llm.tokens", "type", "completion", "feature", feature)
                         .increment(usage.getGenerationTokens());

            // Quality proxy — empty response
            String content = response.getResult().getOutput().getContent();
            if (content == null || content.isBlank()) {
                meterRegistry.counter("llm.empty_response", "feature", feature).increment();
            }

            sample.stop(Timer.builder("llm.call.duration")
                .tag("feature", feature)
                .tag("status", "success")
                .register(meterRegistry));

            return content;

        } catch (Exception ex) {
            meterRegistry.counter("llm.errors", "feature", feature,
                                  "error", ex.getClass().getSimpleName()).increment();
            sample.stop(Timer.builder("llm.call.duration")
                .tag("feature", feature)
                .tag("status", "error")
                .register(meterRegistry));
            throw ex;
        }
    }
}
