@Service
public class TracedChatService {

    private final ChatModel chatModel;
    private final ObservationRegistry observationRegistry;

    public String generate(String feature, Prompt prompt) {
        // Custom observation wrapping the LLM call
        Observation obs = Observation
            .createNotStarted("llm.call", observationRegistry)
            .lowCardinalityKeyValue("feature", feature)
            .lowCardinalityKeyValue("model", "gpt-4o")
            .start();

        try (Observation.Scope scope = obs.openScope()) {
            ChatResponse response = chatModel.call(prompt);

            Long tokens = response.getMetadata().getUsage().getTotalTokens();
            obs.highCardinalityKeyValue("llm.total_tokens", String.valueOf(tokens));

            return response.getResult().getOutput().getContent();
        } catch (Exception ex) {
            obs.error(ex);
            throw ex;
        } finally {
            obs.stop();
        }
    }
}
